/**
 * The block rule for `fs.blocks` pulls (docs/protocol.md → Block-verified, resumable pulls). Pure and
 * electron-free: the Mac's receiver and its tests call this, and the phone's `FsBlocks.kt` implements
 * the same rule. Both are held to `docs/fixtures/fs-blocks.json`, which was generated by a third,
 * independent implementation so neither side grades itself.
 */
import { createHash } from 'node:crypto';

/** Pulls at or below this keep the pre-hash path; blocks apply only above it. */
export const BLOCK_PULL_ABOVE_BYTES = 64 * 1024 * 1024;
export const MIN_BLOCK_SIZE = 1 << 17; // 128 KiB
export const MAX_BLOCK_SIZE = 1 << 24; // 16 MiB
export const MAX_BLOCKS_TARGET = 2000;
/** At most this many digests in one `fs.transfer.blocks` event. */
export const MAX_DIGESTS_PER_EVENT = 256;

/** The smallest power of two in [128 KiB, 16 MiB] giving ≤ 2000 blocks; 16 MiB when none does. */
export function blockSizeFor(size: number): number {
  for (let bs = MIN_BLOCK_SIZE; bs <= MAX_BLOCK_SIZE; bs *= 2) {
    if (Math.ceil(size / bs) <= MAX_BLOCKS_TARGET) return bs;
  }
  return MAX_BLOCK_SIZE;
}

export function blockCountFor(size: number, blockSize: number): number {
  return Math.ceil(size / blockSize);
}

/** SHA-256 over the first [n] raw 32-byte digests (all when omitted): `manifestRoot` / `prefixRoot(n)`. */
export function rootOf(digests: readonly string[], n: number = digests.length): string {
  const h = createHash('sha256');
  for (let i = 0; i < n; i += 1) h.update(Buffer.from(digests[i]!, 'hex'));
  return h.digest('hex');
}

const HEX64 = /^[0-9a-f]{64}$/;

/**
 * Checks one `fs.transfer.blocks` event against what the receiver expects next. Returns the digests
 * to append, or why the event is refused — no gap, no repeat, no reordering, ≤ 256, 64 lowercase hex,
 * never past [blockCount].
 */
export function acceptBlocksEvent(
  expectedFirst: number,
  blockCount: number,
  event: { first?: unknown; sha256?: unknown },
): { ok: true; digests: string[] } | { ok: false; why: string } {
  if (typeof event.first !== 'number' || !Number.isInteger(event.first)) return { ok: false, why: 'first is not an integer' };
  if (event.first !== expectedFirst) return { ok: false, why: `first ${event.first} where ${expectedFirst} was expected` };
  if (!Array.isArray(event.sha256) || event.sha256.length === 0) return { ok: false, why: 'sha256 is not a non-empty array' };
  if (event.sha256.length > MAX_DIGESTS_PER_EVENT) return { ok: false, why: `${event.sha256.length} digests in one event (at most ${MAX_DIGESTS_PER_EVENT})` };
  if (expectedFirst + event.sha256.length > blockCount) return { ok: false, why: `digests run past block ${blockCount}` };
  for (const d of event.sha256) if (typeof d !== 'string' || !HEX64.test(d)) return { ok: false, why: 'a digest is not 64 lowercase hex characters' };
  return { ok: true, digests: event.sha256 as string[] };
}

/**
 * Hashes a byte stream into fixed-size blocks, whatever the chunk boundaries — a 256 KiB bulk chunk
 * can straddle two 128 KiB blocks, and a 1 MiB block spans four chunks. [finish] hashes the short
 * last block.
 */
export class BlockHasher {
  readonly digests: string[] = [];
  private current = createHash('sha256');
  private filled = 0;

  constructor(readonly blockSize: number) {}

  update(chunk: Uint8Array): void {
    let at = 0;
    while (at < chunk.length) {
      const take = Math.min(this.blockSize - this.filled, chunk.length - at);
      this.current.update(chunk.subarray(at, at + take));
      this.filled += take;
      at += take;
      if (this.filled === this.blockSize) this.close();
    }
  }

  /** Closes the last, short block if it has any bytes. Idempotent. */
  finish(): string[] {
    if (this.filled > 0) this.close();
    return this.digests;
  }

  private close(): void {
    this.digests.push(this.current.digest('hex'));
    this.current = createHash('sha256');
    this.filled = 0;
  }
}
